import * as React from "react"
import { graphql } from "gatsby"

import "../scss/main.scss"

import Header from "../components/Header"
import Footer from "../components/Footer"
import AccentDots from "../components/AccentDots"
import Seo from "../components/Seo"

interface PageProps {
  data: {
    file: {
      publicURL: string
    }
  }
}

const About: React.FC<PageProps> = ({ data }) => {
  return (
    <div className="container">
      <Header />
      <div className="gallery-hero">
        <div className="about-photo">
          <img
            src={data.file.publicURL}
            alt="Jayne Hepburn Zikalala"
          />
        </div>
        <h1>My Story</h1>
        <p>
          I'm a visual artist at heart with a keen eye for detail. More
          recently, I've discovered a passion for bird photography, which has
          become a huge part of my creative life. I studied Illustration at
          degree level before completing a Masters in Digital Moving Imagery,
          and those experiences continue to shape my creative work today.
        </p>
        <AccentDots />
      </div>

      <div className="about-sections">
        <section className="about-section">
          <h2>Bird photography</h2>
          <p>
            Bird photography is a creative journey that continues to evolve and
            inspire me. I spend as much time as I can cycling out with my camera
            packed in my bag, searching out those quiet, intimate moments with
            birds in their element. I love capturing their character,
            movement, and energy, and each outing brings something new — it
            never stops inspiring me.
          </p>
        </section>

        <section className="about-section">
          <h2>Creativity &amp; code</h2>
          <p>
            Code is another creative medium for me. I've been working as a
            front-end developer since 2015, and I love making things that are
            interactive, visual, and a bit playful. The games and experiments
            in the Code section started as ideas in my sketchbook and ended up
            as real things you can play.
          </p>
        </section>

        <section className="about-section">
          <h2>More about me</h2>
          <ul className="about-list">
            <li>Passionate cyclist who loves adventures</li>
            <li>Experienced swimmer with a love for open water and the sea</li>
            <li>PADI Open Water &amp; Rescue Diver, black belt in kickboxing</li>
            <li>Loves travelling and exploring new places</li>
            <li>Previously involved in marine conservation and environmental volunteering</li>
          </ul>
        </section>
      </div>

      <Footer />
    </div>
  )
}

export const query = graphql`
  query AboutPageQuery {
    file(sourceInstanceName: { eq: "profile" }, relativePath: { eq: "me.jpg" }) {
      publicURL
    }
  }
`

export const Head = () => <Seo title="My Story" description="The story behind enerjay — Jayne Hepburn Zikalala." />

export default About
